impl<'input,I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>> ParserRecog<'input, BaseParserType<'input,I>> for OpenSearchPPLParserExt<'input>{}

impl<'input,I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>> Actions<'input, BaseParserType<'input,I>> for OpenSearchPPLParserExt<'input>{
	fn get_grammar_file_name(&self) -> & str{ "OpenSearchPPLParser.g4"}

   	fn get_rule_names(&self) -> &[& str] {&ruleNames}

   	fn get_vocabulary(&self) -> &dyn Vocabulary { &**VOCABULARY }
	fn sempred(_localctx: Option<&(dyn OpenSearchPPLParserContext<'input> + 'input)>, rule_index: i32, pred_index: i32,
			   recog:&mut BaseParserType<'input,I>
	)->bool{
		match rule_index {
					11 => OpenSearchPPLParser::<'input,I>::searchExpression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					176 => OpenSearchPPLParser::<'input,I>::logicalExpression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					177 => OpenSearchPPLParser::<'input,I>::expression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
					179 => OpenSearchPPLParser::<'input,I>::valueExpression_sempred(_localctx.and_then(|x|x.downcast_ref()), pred_index, recog),
			_ => true
		}
	}
}

impl<'input, I> OpenSearchPPLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	fn searchExpression_sempred(_localctx: Option<&SearchExpressionContext<'input>>, pred_index:i32,
						recog:&mut <Self as Deref>::Target
		) -> bool {
		match pred_index {
				0=>{
					recog.precpred(None, 3)
				}
				1=>{
					recog.precpred(None, 2)
				}
			_ => true
		}
	}
	fn logicalExpression_sempred(_localctx: Option<&LogicalExpressionContext<'input>>, pred_index:i32,
						recog:&mut <Self as Deref>::Target
		) -> bool {
		match pred_index {
				2=>{
					recog.precpred(None, 4)
				}
				3=>{
					recog.precpred(None, 3)
				}
				4=>{
					recog.precpred(None, 2)
				}
			_ => true
		}
	}
	fn expression_sempred(_localctx: Option<&ExpressionContext<'input>>, pred_index:i32,
						recog:&mut <Self as Deref>::Target
		) -> bool {
		match pred_index {
				5=>{
					recog.precpred(None, 4)
				}
				6=>{
					recog.precpred(None, 2)
				}
				7=>{
					recog.precpred(None, 3)
				}
				8=>{
					recog.precpred(None, 1)
				}
			_ => true
		}
	}
	fn valueExpression_sempred(_localctx: Option<&ValueExpressionContext<'input>>, pred_index:i32,
						recog:&mut <Self as Deref>::Target
		) -> bool {
		match pred_index {
				9=>{
					recog.precpred(None, 12)
				}
				10=>{
					recog.precpred(None, 11)
				}
				11=>{
					recog.precpred(None, 5)
				}
			_ => true
		}
	}
}
