impl<'input, I> OpenSearchPPLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn root(&mut self,)
	-> Result<Rc<RootContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = RootContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 0, RULE_root);
        let mut _localctx: Rc<RootContextAll> = _localctx;
		let mut _la: i32 = -1;
		let result: Result<(), ANTLRError> = (|| {

			//recog.base.enter_outer_alt(_localctx.clone(), 1)?;
			recog.base.enter_outer_alt(None, 1)?;
			{
			recog.base.set_state(529);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			if (((_la) & !0x3f) == 0 && ((1usize << _la) & 3221225470) != 0) || ((((_la - 32)) & !0x3f) == 0 && ((1usize << (_la - 32)) & 3774709759) != 0) || ((((_la - 67)) & !0x3f) == 0 && ((1usize << (_la - 67)) & 4286570495) != 0) || ((((_la - 99)) & !0x3f) == 0 && ((1usize << (_la - 99)) & 4288675815) != 0) || ((((_la - 131)) & !0x3f) == 0 && ((1usize << (_la - 131)) & 4294967295) != 0) || ((((_la - 166)) & !0x3f) == 0 && ((1usize << (_la - 166)) & 4294909949) != 0) || ((((_la - 198)) & !0x3f) == 0 && ((1usize << (_la - 198)) & 2954887167) != 0) || ((((_la - 237)) & !0x3f) == 0 && ((1usize << (_la - 237)) & 4294017155) != 0) || ((((_la - 269)) & !0x3f) == 0 && ((1usize << (_la - 269)) & 4294967039) != 0) || ((((_la - 301)) & !0x3f) == 0 && ((1usize << (_la - 301)) & 4294967295) != 0) || ((((_la - 333)) & !0x3f) == 0 && ((1usize << (_la - 333)) & 4294967295) != 0) || ((((_la - 365)) & !0x3f) == 0 && ((1usize << (_la - 365)) & 4288675839) != 0) || ((((_la - 397)) & !0x3f) == 0 && ((1usize << (_la - 397)) & 4294967295) != 0) || ((((_la - 429)) & !0x3f) == 0 && ((1usize << (_la - 429)) & 4294966783) != 0) || ((((_la - 461)) & !0x3f) == 0 && ((1usize << (_la - 461)) & 4294967295) != 0) || ((((_la - 493)) & !0x3f) == 0 && ((1usize << (_la - 493)) & 31370271) != 0) {
				{
				/*InvokeRule pplStatement*/
				recog.base.set_state(528);
				recog.pplStatement()?;

				}
			}

			recog.base.set_state(531);
			recog.base.match_token(OpenSearchPPLParser_EOF,&mut recog.err_handler)?;

			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
