//------------------- commandName ----------------
pub type CommandNameContextAll<'input> = CommandNameContext<'input>;


pub type CommandNameContext<'input> = BaseParserRuleContext<'input,CommandNameContextExt<'input>>;

#[derive(Clone)]
pub struct CommandNameContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> OpenSearchPPLParserContext<'input> for CommandNameContext<'input>{}

impl<'input,'a> Listenable<dyn OpenSearchPPLParserListener<'input> + 'a> for CommandNameContext<'input>{
		fn enter(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_commandName(self);
			Ok(())
		}
		fn exit(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_commandName(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input,'a> Visitable<dyn OpenSearchPPLParserVisitor<'input> + 'a> for CommandNameContext<'input>{
	fn accept(&self,visitor: &mut (dyn OpenSearchPPLParserVisitor<'input> + 'a)) {
		visitor.visit_commandName(self);
	}
}

impl<'input> CustomRuleContext<'input> for CommandNameContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = OpenSearchPPLParserContextType;
	fn get_rule_index(&self) -> usize { RULE_commandName }
	//fn type_rule_index() -> usize where Self: Sized { RULE_commandName }
}
antlr4rust::tid!{CommandNameContextExt<'a>}

impl<'input> CommandNameContextExt<'input>{
	fn new(parent: Option<Rc<dyn OpenSearchPPLParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<CommandNameContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,CommandNameContextExt{

				ph:PhantomData
			}),
		)
	}
}

