pub trait ForeachEvalCommandContextAttrs<'input>: OpenSearchPPLParserContext<'input> + BorrowMut<ForeachEvalCommandContextExt<'input>>{

/// Retrieves first TerminalNode corresponding to token EVAL
/// Returns `None` if there is no child corresponding to token EVAL
fn EVAL(&self) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_EVAL, 0)
}
fn foreachEvalClause_all(&self) ->  Vec<Rc<ForeachEvalClauseContextAll<'input>>> where Self:Sized{
	self.children_of_type()
}
fn foreachEvalClause(&self, i: usize) -> Option<Rc<ForeachEvalClauseContextAll<'input>>> where Self:Sized{
	self.child_of_type(i)
}
/// Retrieves all `TerminalNode`s corresponding to token COMMA in current rule
fn COMMA_all(&self) -> Vec<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>>  where Self:Sized{
	self.children_of_type()
}
/// Retrieves 'i's TerminalNode corresponding to token COMMA, starting from 0.
/// Returns `None` if number of children corresponding to token COMMA is less or equal than `i`.
fn COMMA(&self, i: usize) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_COMMA, i)
}

}

impl<'input> ForeachEvalCommandContextAttrs<'input> for ForeachEvalCommandContext<'input>{}

impl<'input, I> OpenSearchPPLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn foreachEvalCommand(&mut self,)
	-> Result<Rc<ForeachEvalCommandContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = ForeachEvalCommandContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 138, RULE_foreachEvalCommand);
        let mut _localctx: Rc<ForeachEvalCommandContextAll> = _localctx;
		let mut _la: i32 = -1;
		let result: Result<(), ANTLRError> = (|| {

			//recog.base.enter_outer_alt(_localctx.clone(), 1)?;
			recog.base.enter_outer_alt(None, 1)?;
			{
			recog.base.set_state(1137);
			recog.base.match_token(OpenSearchPPLParser_EVAL,&mut recog.err_handler)?;

			/*InvokeRule foreachEvalClause*/
			recog.base.set_state(1138);
			recog.foreachEvalClause()?;

			recog.base.set_state(1143);
			recog.err_handler.sync(&mut recog.base)?;
			_la = recog.base.input.la(1);
			while _la==OpenSearchPPLParser_COMMA {
				{
				{
				recog.base.set_state(1139);
				recog.base.match_token(OpenSearchPPLParser_COMMA,&mut recog.err_handler)?;

				/*InvokeRule foreachEvalClause*/
				recog.base.set_state(1140);
				recog.foreachEvalClause()?;

				}
				}
				recog.base.set_state(1145);
				recog.err_handler.sync(&mut recog.base)?;
				_la = recog.base.input.la(1);
			}
			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
