pub type IndexablePathContextAll<'input> = IndexablePathContext<'input>;


pub type IndexablePathContext<'input> = BaseParserRuleContext<'input,IndexablePathContextExt<'input>>;

#[derive(Clone)]
pub struct IndexablePathContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> OpenSearchPPLParserContext<'input> for IndexablePathContext<'input>{}

impl<'input,'a> Listenable<dyn OpenSearchPPLParserListener<'input> + 'a> for IndexablePathContext<'input>{
		fn enter(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_indexablePath(self);
			Ok(())
		}
		fn exit(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_indexablePath(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input,'a> Visitable<dyn OpenSearchPPLParserVisitor<'input> + 'a> for IndexablePathContext<'input>{
	fn accept(&self,visitor: &mut (dyn OpenSearchPPLParserVisitor<'input> + 'a)) {
		visitor.visit_indexablePath(self);
	}
}

impl<'input> CustomRuleContext<'input> for IndexablePathContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = OpenSearchPPLParserContextType;
	fn get_rule_index(&self) -> usize { RULE_indexablePath }
	//fn type_rule_index() -> usize where Self: Sized { RULE_indexablePath }
}
antlr4rust::tid!{IndexablePathContextExt<'a>}

impl<'input> IndexablePathContextExt<'input>{
	fn new(parent: Option<Rc<dyn OpenSearchPPLParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<IndexablePathContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,IndexablePathContextExt{

				ph:PhantomData
			}),
		)
	}
}

pub trait IndexablePathContextAttrs<'input>: OpenSearchPPLParserContext<'input> + BorrowMut<IndexablePathContextExt<'input>>{

fn pathElement_all(&self) ->  Vec<Rc<PathElementContextAll<'input>>> where Self:Sized{
	self.children_of_type()
}
fn pathElement(&self, i: usize) -> Option<Rc<PathElementContextAll<'input>>> where Self:Sized{
	self.child_of_type(i)
}
/// Retrieves all `TerminalNode`s corresponding to token DOT in current rule
fn DOT_all(&self) -> Vec<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>>  where Self:Sized{
	self.children_of_type()
}
/// Retrieves 'i's TerminalNode corresponding to token DOT, starting from 0.
/// Returns `None` if number of children corresponding to token DOT is less or equal than `i`.
fn DOT(&self, i: usize) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_DOT, i)
}
fn stringLiteral(&self) -> Option<Rc<StringLiteralContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}

}

impl<'input> IndexablePathContextAttrs<'input> for IndexablePathContext<'input>{}

