impl<'input, I> OpenSearchPPLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn hintPair(&mut self,)
	-> Result<Rc<HintPairContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = HintPairContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 304, RULE_hintPair);
        let mut _localctx: Rc<HintPairContextAll> = _localctx;
		let result: Result<(), ANTLRError> = (|| {

			recog.base.set_state(1997);
			recog.err_handler.sync(&mut recog.base)?;
			match recog.base.input.la(1) {
			OpenSearchPPLParser_LEFT_HINT 
				=> {
					let tmp = LeftHintContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 1)?;
					_localctx = tmp;
					{
					recog.base.set_state(1987);
					let tmp = recog.base.match_token(OpenSearchPPLParser_LEFT_HINT,&mut recog.err_handler)?;
					if let HintPairContextAll::LeftHintContext(ctx) = cast_mut::<_,HintPairContextAll >(&mut _localctx){
					ctx.leftHintKey = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					recog.base.set_state(1988);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					recog.base.set_state(1989);
					recog.base.match_token(OpenSearchPPLParser_ID,&mut recog.err_handler)?;

					recog.base.set_state(1990);
					recog.base.match_token(OpenSearchPPLParser_EQUAL,&mut recog.err_handler)?;

					/*InvokeRule ident*/
					recog.base.set_state(1991);
					let tmp = recog.ident()?;
					if let HintPairContextAll::LeftHintContext(ctx) = cast_mut::<_,HintPairContextAll >(&mut _localctx){
					ctx.leftHintValue = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					}
				}

			OpenSearchPPLParser_RIGHT_HINT 
				=> {
					let tmp = RightHintContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 2)?;
					_localctx = tmp;
					{
					recog.base.set_state(1992);
					let tmp = recog.base.match_token(OpenSearchPPLParser_RIGHT_HINT,&mut recog.err_handler)?;
					if let HintPairContextAll::RightHintContext(ctx) = cast_mut::<_,HintPairContextAll >(&mut _localctx){
					ctx.rightHintKey = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					recog.base.set_state(1993);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					recog.base.set_state(1994);
					recog.base.match_token(OpenSearchPPLParser_ID,&mut recog.err_handler)?;

					recog.base.set_state(1995);
					recog.base.match_token(OpenSearchPPLParser_EQUAL,&mut recog.err_handler)?;

					/*InvokeRule ident*/
					recog.base.set_state(1996);
					let tmp = recog.ident()?;
					if let HintPairContextAll::RightHintContext(ctx) = cast_mut::<_,HintPairContextAll >(&mut _localctx){
					ctx.rightHintValue = Some(tmp.clone()); } else {unreachable!("cant cast");}  

					}
				}

				_ => Err(ANTLRError::NoAltError(NoViableAltError::new(&mut recog.base)))?
			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
