impl<'input, I> OpenSearchPPLParser<'input, I>
where
    I: TokenStream<'input, TF = LocalTokenFactory<'input> > + TidAble<'input>,
{
	pub fn ffLogicalExpression(&mut self,)
	-> Result<Rc<FfLogicalExpressionContextAll<'input>>,ANTLRError> {
		let mut recog = self;
		let _parentctx = recog.ctx.take();
		let mut _localctx = FfLogicalExpressionContextExt::new(_parentctx.clone(), recog.base.get_state());
        recog.base.enter_rule(_localctx.clone(), 350, RULE_ffLogicalExpression);
        let mut _localctx: Rc<FfLogicalExpressionContextAll> = _localctx;
		let result: Result<(), ANTLRError> = (|| {

			recog.base.set_state(2174);
			recog.err_handler.sync(&mut recog.base)?;
			match  recog.interpreter.adaptive_predict(201,&mut recog.base)? {
				1 =>{
					let tmp = StringDotlogicalExpressionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 1)?;
					_localctx = tmp;
					{
					/*InvokeRule stringLiteral*/
					recog.base.set_state(2159);
					recog.stringLiteral()?;

					recog.base.set_state(2160);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					/*InvokeRule logicalExpression*/
					recog.base.set_state(2161);
					recog.logicalExpression_rec(0)?;

					}
				}
			,
				2 =>{
					let tmp = StringDotlogicalExpressionDotStringContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 2)?;
					_localctx = tmp;
					{
					/*InvokeRule stringLiteral*/
					recog.base.set_state(2163);
					recog.stringLiteral()?;

					recog.base.set_state(2164);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					/*InvokeRule logicalExpression*/
					recog.base.set_state(2165);
					recog.logicalExpression_rec(0)?;

					recog.base.set_state(2166);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					/*InvokeRule stringLiteral*/
					recog.base.set_state(2167);
					recog.stringLiteral()?;

					}
				}
			,
				3 =>{
					let tmp = LogicalExpressionDotStringContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 3)?;
					_localctx = tmp;
					{
					/*InvokeRule logicalExpression*/
					recog.base.set_state(2169);
					recog.logicalExpression_rec(0)?;

					recog.base.set_state(2170);
					recog.base.match_token(OpenSearchPPLParser_DOT,&mut recog.err_handler)?;

					/*InvokeRule stringLiteral*/
					recog.base.set_state(2171);
					recog.stringLiteral()?;

					}
				}
			,
				4 =>{
					let tmp = FfStandardLogicalExpressionContextExt::new(&**_localctx);
					recog.base.enter_outer_alt(Some(tmp.clone()), 4)?;
					_localctx = tmp;
					{
					/*InvokeRule logicalExpression*/
					recog.base.set_state(2173);
					recog.logicalExpression_rec(0)?;

					}
				}

				_ => {}
			}
			Ok(())
		})();
		match result {
		Ok(_)=>{},
        Err(e @ ANTLRError::FallThrough(_)) => return Err(e),
		Err(ref re) => {
				//_localctx.exception = re;
				recog.err_handler.report_error(&mut recog.base, re);
				recog.err_handler.recover(&mut recog.base, re)?;
			}
		}
		recog.base.exit_rule()?;

		Ok(_localctx)
	}
}
