	/// Returns `None` if there is no child corresponding to token RT_PRTHS
	fn RT_PRTHS(&self) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
		self.get_token(OpenSearchPPLParser_RT_PRTHS, 0)
	}
