//------------------- ident ----------------
pub type IdentContextAll<'input> = IdentContext<'input>;


pub type IdentContext<'input> = BaseParserRuleContext<'input,IdentContextExt<'input>>;

#[derive(Clone)]
pub struct IdentContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> OpenSearchPPLParserContext<'input> for IdentContext<'input>{}

impl<'input,'a> Listenable<dyn OpenSearchPPLParserListener<'input> + 'a> for IdentContext<'input>{
		fn enter(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_ident(self);
			Ok(())
		}
		fn exit(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_ident(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input,'a> Visitable<dyn OpenSearchPPLParserVisitor<'input> + 'a> for IdentContext<'input>{
	fn accept(&self,visitor: &mut (dyn OpenSearchPPLParserVisitor<'input> + 'a)) {
		visitor.visit_ident(self);
	}
}

impl<'input> CustomRuleContext<'input> for IdentContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = OpenSearchPPLParserContextType;
	fn get_rule_index(&self) -> usize { RULE_ident }
	//fn type_rule_index() -> usize where Self: Sized { RULE_ident }
}
antlr4rust::tid!{IdentContextExt<'a>}

impl<'input> IdentContextExt<'input>{
	fn new(parent: Option<Rc<dyn OpenSearchPPLParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<IdentContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,IdentContextExt{

				ph:PhantomData
			}),
		)
	}
}

pub trait IdentContextAttrs<'input>: OpenSearchPPLParserContext<'input> + BorrowMut<IdentContextExt<'input>>{

/// Retrieves first TerminalNode corresponding to token ID
/// Returns `None` if there is no child corresponding to token ID
fn ID(&self) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_ID, 0)
}
/// Retrieves first TerminalNode corresponding to token DOT
/// Returns `None` if there is no child corresponding to token DOT
fn DOT(&self) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_DOT, 0)
}
/// Retrieves all `TerminalNode`s corresponding to token BACKTICK in current rule
fn BACKTICK_all(&self) -> Vec<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>>  where Self:Sized{
	self.children_of_type()
}
/// Retrieves 'i's TerminalNode corresponding to token BACKTICK, starting from 0.
/// Returns `None` if number of children corresponding to token BACKTICK is less or equal than `i`.
fn BACKTICK(&self, i: usize) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_BACKTICK, i)
}
fn ident(&self) -> Option<Rc<IdentContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}
/// Retrieves first TerminalNode corresponding to token BQUOTA_STRING
/// Returns `None` if there is no child corresponding to token BQUOTA_STRING
fn BQUOTA_STRING(&self) -> Option<Rc<TerminalNode<'input,OpenSearchPPLParserContextType>>> where Self:Sized{
	self.get_token(OpenSearchPPLParser_BQUOTA_STRING, 0)
}
fn keywordsCanBeId(&self) -> Option<Rc<KeywordsCanBeIdContextAll<'input>>> where Self:Sized{
	self.child_of_type(0)
}

}

