//------------------- searchableKeyWord ----------------
pub type SearchableKeyWordContextAll<'input> = SearchableKeyWordContext<'input>;


pub type SearchableKeyWordContext<'input> = BaseParserRuleContext<'input,SearchableKeyWordContextExt<'input>>;

#[derive(Clone)]
pub struct SearchableKeyWordContextExt<'input>{
ph:PhantomData<&'input str>
}

impl<'input> OpenSearchPPLParserContext<'input> for SearchableKeyWordContext<'input>{}

impl<'input,'a> Listenable<dyn OpenSearchPPLParserListener<'input> + 'a> for SearchableKeyWordContext<'input>{
		fn enter(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.enter_every_rule(self)?;
			listener.enter_searchableKeyWord(self);
			Ok(())
		}
		fn exit(&self,listener: &mut (dyn OpenSearchPPLParserListener<'input> + 'a)) -> Result<(), ANTLRError> {
			listener.exit_searchableKeyWord(self);
			listener.exit_every_rule(self)?;
			Ok(())
		}
}

impl<'input,'a> Visitable<dyn OpenSearchPPLParserVisitor<'input> + 'a> for SearchableKeyWordContext<'input>{
	fn accept(&self,visitor: &mut (dyn OpenSearchPPLParserVisitor<'input> + 'a)) {
		visitor.visit_searchableKeyWord(self);
	}
}

impl<'input> CustomRuleContext<'input> for SearchableKeyWordContextExt<'input>{
	type TF = LocalTokenFactory<'input>;
	type Ctx = OpenSearchPPLParserContextType;
	fn get_rule_index(&self) -> usize { RULE_searchableKeyWord }
	//fn type_rule_index() -> usize where Self: Sized { RULE_searchableKeyWord }
}
antlr4rust::tid!{SearchableKeyWordContextExt<'a>}

impl<'input> SearchableKeyWordContextExt<'input>{
	fn new(parent: Option<Rc<dyn OpenSearchPPLParserContext<'input> + 'input > >, invoking_state: i32) -> Rc<SearchableKeyWordContextAll<'input>> {
		Rc::new(
			BaseParserRuleContext::new_parser_ctx(parent, invoking_state,SearchableKeyWordContextExt{

				ph:PhantomData
			}),
		)
	}
}

